properties.query:
let alertWindow = 15m;
let criticalContainers = dynamic(["telemetry-tap","mavlink-router","pgse-stub","auth-stub"]);
let connFloodGate = 150;
let KillEvents =
    UAVContainerOps_CL
    | where TimeGenerated > ago(alertWindow)
    | where ContainerName in (criticalContainers)
    | where Action in ("stop", "kill")
    | project KillTime = TimeGenerated, UAVId, ContainerName, Namespace, ActorId, Action, TimeBin = bin(TimeGenerated, 5m);
let ConnBurst =
    UAVContainerOps_CL
    | where TimeGenerated > ago(alertWindow)
    | where ContainerName in (criticalContainers)
    | where ConnCount > connFloodGate
    | summarize MaxConnCount = max(ConnCount) by ContainerName, TimeBin = bin(TimeGenerated, 5m);
KillEvents
| join kind=inner (ConnBurst) on ContainerName, TimeBin
| extend TriggerReason = strcat(ContainerName, "_slowloris_연결폭증후_강제중단_", Action)
| extend Severity = "High"
| project KillTime, UAVId, ContainerName, Namespace, ActorId, Action, MaxConnCount, TriggerReason, Severity
| order by KillTime desc
